+const bagButton = document.querySelector(".bag-button");
+const bagCount = document.querySelector(".bag-count");
+const statusRegion = document.querySelector(".status-region");
+const addToCartButtons = document.querySelectorAll(".add-to-cart");
+const saveButtons = document.querySelectorAll(".save-item");
+const copyCodeButtons = document.querySelectorAll(".copy-code");
+
+let bagItems = 0;
+let statusTimeoutId;
+
+function announceStatus(message) {
+  statusRegion.textContent = message;
+  statusRegion.classList.add("is-visible");
+
+  window.clearTimeout(statusTimeoutId);
+  statusTimeoutId = window.setTimeout(() => {
+    statusRegion.classList.remove("is-visible");
+  }, 2200);
+}
+
+function updateBagLabel() {
+  const itemLabel = bagItems === 1 ? "item" : "items";
+  bagCount.textContent = String(bagItems);
+  bagButton.setAttribute("aria-label", `Shopping bag with ${bagItems} ${itemLabel}`);
+}
+
+addToCartButtons.forEach((button) => {
+  const productName = button.dataset.productName;
+  button.setAttribute("aria-label", `Add to bag: ${productName}`);
+
+  button.addEventListener("click", () => {
+    bagItems += 1;
+    updateBagLabel();
+    announceStatus(`${productName} added to bag.`);
+  });
+});
+
+saveButtons.forEach((button) => {
+  const productName = button.dataset.productName;
+  button.setAttribute("aria-label", `Save ${productName}`);
+
+  button.addEventListener("click", () => {
+    const isSaved = button.getAttribute("aria-pressed") === "true";
+    const nextSavedState = !isSaved;
+
+    button.setAttribute("aria-pressed", String(nextSavedState));
+    button.textContent = nextSavedState ? "Saved" : "Save";
+
+    const actionText = nextSavedState ? "saved for later" : "removed from saved items";
+    announceStatus(`${productName} ${actionText}.`);
+  });
+});
+
+copyCodeButtons.forEach((button) => {
+  const code = button.dataset.code;
+
+  button.addEventListener("click", async () => {
+    try {
+      await navigator.clipboard.writeText(code);
+      announceStatus(`Promo code ${code} copied to clipboard.`);
+    } catch (error) {
+      announceStatus(`Promo code ${code}. Copy manually if clipboard access is unavailable.`);
+    }
+  });
+});
+
+updateBagLabel();
